STOCK = 4
def quote(quantity):
    if type(quantity) is not int or quantity < 0:
        raise ValueError('quantity must be a nonnegative integer')
    return {'total': str(Decimal(PRICE_CENTS * quantity) / Decimal(100)),
            'currency': 'USD', 'available': quantity <= STOCK}

